// De-duplicate on record_id (falls back to email|item_ref).
// PayRequest 2026-11-06: a retry must not send a second message for one row.
const rows = $input.all();
const seen = new Set();
const out = [];
for (const item of rows) {
  const p = item.json;
  const k = String(p.record_id !== undefined && p.record_id !== null
    ? p.record_id : (String(p.email) + '|' + String(p.item_ref)));
  if (seen.has(k)) continue;
  seen.add(k);
  out.push({ json: Object.assign({}, p) });
}
return out;

// Deterministic template logic. Dates are relative so the fixture never goes stale.
const cfg = $('CONFIG').first().json;
const rows = $input.all();
const daysBetween = function (s) {
  const t = Date.parse(String(s || '') + 'T00:00:00Z');
  return Number.isFinite(t) ? Math.max(0, Math.floor((Date.now() - t) / 86400000)) : 0;
};
// Terminal statuses are derived from what THIS template writes back, plus 'done'.
// Without this guard a second daily run re-sends the same message: the exact
// defect PayRequest 2026-11-06 calls out ("a retry must not send repeated emails").
const TERMINAL = new Set((Array.isArray(cfg.terminal_status) ? cfg.terminal_status : ['done'])
  .map(function (s) { return String(s).toLowerCase(); }));
const flag = function (p, ok) {
  const st = String(p.status === undefined || p.status === null ? '' : p.status).toLowerCase();
  if (TERMINAL.has(st)) return false;
  const prev = (p.needs_action === undefined) ? true : (p.needs_action === true);
  return prev && ok === true;
};
// ``putuskan`` MENETAPKAN keputusan, bukan mempersempitnya. Dipakai oleh bata yang
// memang menjadi tempat keputusan diambil (``saring_nilai``).
//
// ``flag`` bersifat DAN: hasilnya ``prev && ok``. Selama ambang dipasang di dua bata,
// bata pertama dapat mematikan baris yang seharusnya diterima bata kedua. Terukur
// 15 Nov 2026 pada wa-trial-expiry: ``hitung_umur.batas_hari=14`` sedangkan
// ``saring_nilai`` memakai ``days_since == 12``, sehingga bata pertama menilai
// ``12 >= 14`` salah untuk SEMUA baris, ``needs_action`` menjadi false di mana-mana,
// dan bata kedua tidak bisa menghidupkannya lagi - cabang true menerima 0 baris
// (``true=0 false=4``) padahal fixture sudah benar.
const putuskan = function (p, ok) {
  const st = String(p.status === undefined || p.status === null ? '' : p.status).toLowerCase();
  if (TERMINAL.has(st)) return false;
  return ok === true;
};
// Bata ini HANYA menurunkan days_since. Ia tidak lagi memutuskan
// needs_action lewat ``d >= batas_hari``: keputusan itu milik ``saring_nilai``,
// dan memasang ambang di dua tempat membuat keduanya bisa bertentangan.
const out = [];
for (const item of rows) {
  const p = item.json;
  const d = daysBetween(p["last_activity"]);
  out.push({ json: Object.assign({}, p, { days_since: d }) });
}
return out;

