  const st = String(p.status === undefined || p.status === null ? '' : p.status).toLowerCase();
  if (TERMINAL.has(st)) return false;
  return ok === true;
};
const tpl = String(cfg.message_template || '');
const subjTpl = String(cfg.subject_template || '');
const larang = { days_since: 1, umur_hari: 1, needs_action: 1, skor: 1, record_id: 1 };
const angka = function (p) {
  const tetap = ['nilai_utama', 'jumlah', 'total', 'amount_due', 'amount', 'nilai'];
  for (let i = 0; i < tetap.length; i++) {
    const k = tetap[i];
    if (typeof p[k] === 'number') return p[k];
  }
  const kunci = Object.keys(p);
  for (let i = 0; i < kunci.length; i++) {
    const k = kunci[i];
    if (!larang[k] && typeof p[k] === 'number') return p[k];
  }
  return '';
};
const peta = { name: 'contact_name', item: 'item_ref', days: 'days_since',
               value: 'nilai_utama', count: 'jumlah' };
const isi = function (s, p) {
  return String(s).replace(/\{\{([a-z_]+)\}\}/g, function (m, k) {
    let v;
    if (k === 'value') {
      // "deposit of {{value}}": ambil kolom angka yang benar-benar ada.
      v = angka(p);
    } else if (k === 'count') {
      // Seluruh pemakaian {{count}} bersifat batch ("{{count}} items", "{{count}}
      // rows"), jadi jumlah baris pada tahap ini adalah jawaban yang tepat.
      v = (typeof p.jumlah === 'number') ? p.jumlah : rows.length;
    } else {
      let f = peta[k];
      // {{days}} memakai days_since hasil hitung_umur; bila bata itu tidak ada,
      // umur_hari dari sumber adalah nilai yang sama sebelum dihitung ulang.
      if (k === 'days' && (p[f] === undefined || p[f] === null)) f = 'umur_hari';
      v = (f && p[f] !== undefined && p[f] !== null) ? p[f] : '';
    }
    return (v === '' || v === undefined || v === null) ? '' : String(v);
  });
};
