// Normalise before any decision runs.
// Trim whitespace, lower-case the fields used for matching, and rewrite
// date-like fields as YYYY-MM-DD so a sender typing " 2026-11-03 " and
// "03/11/2026" cannot change the outcome of a comparison.
const rows = $input.all();
const POLA_TANGGAL = /(date|_at$|^at$|tanggal|deadline|due|expiry|expires)/i;
const POLA_KUNCI = /(email|status|kategori|category|channel|sumber|source|tipe|type)/i;
const keTanggal = function (v) {
  const s = String(v === undefined || v === null ? '' : v).trim();
  if (!s) return s;
  const t = Date.parse(s);
  return Number.isFinite(t) ? new Date(t).toISOString().slice(0, 10) : s;
};
const out = [];
for (const item of rows) {
  const p = item.json || {};
  const q = {};
  for (const k of Object.keys(p)) {
    let v = p[k];
    if (typeof v === 'string') {
      v = v.trim();
      if (POLA_TANGGAL.test(k)) v = keTanggal(v);
      else if (POLA_KUNCI.test(k)) v = v.toLowerCase();
    }
    q[k] = v;
  }
  out.push({ json: q });
}
return out;

// Run receipt: one row per processed record, plus a run-level row when the
// run produced no records. Written to the "Run Log" tab so the buyer can read
// execution history without opening n8n.
const rows = $input.all();
const ts = new Date().toISOString();
const SLUG = 'age-0101-chase-lead';
const pilih = function (p, kunci) {
  for (const k of kunci) {
    const v = p[k];
    if (v !== undefined && v !== null && String(v) !== '') return String(v);
  }
  return '';
};
const out = [];
for (const item of rows) {
  const p = item.json || {};
  out.push({ json: {
    triggered_at: ts,
    record_id: pilih(p, ['record_id', 'id', 'email', 'item_ref']) || (SLUG + ':' + out.length),
    action_taken: pilih(p, ['action_taken', 'subject', 'message_subject', 'message']).slice(0, 180)
      || 'Processed by ' + SLUG,
    status: 'SUCCESS',
    workflow: SLUG,
    rows_in_run: rows.length
  } });
}
if (out.length === 0) {
  out.push({ json: {
    triggered_at: ts,
    record_id: 'run:' + ts,
    action_taken: 'Run finished with no rows to process',
    status: 'SUCCESS',
    workflow: SLUG,
    rows_in_run: 0
  } });
}
return out;

// Failure receipt. Reached from the error output of any credential node, so
// this node can receive items from more than one source: it never reads
// $json directly, only item.json, and names the failing node per item.
const rows = $input.all();
const ts = new Date().toISOString();
const SLUG = 'age-0101-chase-lead';
const out = [];
for (const item of rows) {
  const p = item.json || {};
  // n8n mengirim galat pada cabang galat sebagai STRING di p.error
  // (terukur 16 Nov 2026: {"error": "simulated upstream failure [line 1]"}),
  // bukan objek Error. Versi pertama hanya membaca p.error.message sehingga
  // setiap resi gagal berbunyi "Unknown error" - resi yang tidak memberi tahu
  // apa pun. Kedua bentuk ditangani di sini.
  const e = p.error;
  let pesan;
  if (typeof e === 'string' && e) pesan = e;
  else if (e && typeof e === 'object') pesan = String(e.message || e.description || e.error || 'Unknown error');
  else pesan = String(p.message || 'Unknown error');
  out.push({ json: {
    triggered_at: ts,
    record_id: String(p.record_id || p.id || ('error:' + ts)),
    action_taken: ('FAILED: ' + pesan).slice(0, 180),
    status: 'FAILED',
    workflow: SLUG,
    rows_in_run: rows.length
  } });
}
if (out.length === 0) {
  out.push({ json: {
    triggered_at: ts,
    record_id: 'error:' + ts,
    action_taken: 'FAILED: error branch reached with no error item',
    status: 'FAILED',
    workflow: SLUG,
    rows_in_run: 0
  } });
}
return out;
